                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            touches_edge = False

            while stack:
                x, y = stack.pop()
                cells.append((x, y))
                if x in (0, h - 1) or y in (0, w - 1):
                    touches_edge = True
                for nx, ny in ((x - 1, y), (x + 1, y), (x, y - 1), (x, y + 1)):
                    if (0 <= nx < h and 0 <= ny < w and
                            grid[nx][ny] == bg and (nx, ny) not in seen):
                        seen.add((nx, ny))
                        stack.append((nx, ny))

            if not touches_edge:
                height = max(x for x, _ in cells) - min(x for x, _ in cells) + 1
                width = max(y for _, y in cells) - min(y for _, y in cells) + 1
                fill = 2 if height % 2 == 0 and width % 2 == 0 else 7
                for x, y in cells:
                    out[x][y] = fill

